using namespace std;

long long a, b, best = LLONG_MAX;

// For a fixed k, the smallest x makes k(A+x) >= B; y is then forced.
void test(long long k) {
    long long x = max(0LL, (b + k - 1) / k - a);
    best = min(best, x + k * (a + x) - b);
}

int main() {
    cin >> a >> b;
    long long r = (long long)sqrtl((long double)b);
    while (r * r > b) r--;
    while ((r + 1) * (r + 1) <= b) r++;
    r += 2;
    for (long long k = 1; k <= min(b, r); k++) test(k);  // small k directly
    for (long long q = 1; q <= r; q++) test((b + q - 1) / q);  // large k grouped by ceil(B/k)
    test(max(1LL, (b + a - 1) / a));  // boundary where x becomes 0
    cout << best << "\n";
}

import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return null;
        ByteArrayOutputStream sb = new ByteArrayOutputStream();
        while (c != -1 && c > ' ') { sb.write(c); c = read(); }
        return sb.toString(java.nio.charset.StandardCharsets.UTF_8);
    }

    static long a, b, best = Long.MAX_VALUE;

    // For a fixed k, the smallest x makes k(A+x) >= B; y is then forced.
    static void test(long k) {
        long x = Math.max(0, (b + k - 1) / k - a);
        best = Math.min(best, x + k * (a + x) - b);
    }

    public static void main(String[] args) throws IOException {
        a = nextLong();
        b = nextLong();
        long r = (long) Math.sqrt((double) b);
        while (r * r > b) r--;
        while ((r + 1) * (r + 1) <= b) r++;
        r += 2;
        for (long k = 1; k <= Math.min(b, r); k++) test(k);  // small k directly
        for (long q = 1; q <= r; q++) test((b + q - 1) / q);  // large k grouped by ceil(B/k)
        test(Math.max(1, (b + a - 1) / a));  // boundary where x becomes 0
        System.out.println(best);
    }
}

package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func readToken() string {
	c, err := rd.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return ""
	}
	b := []byte{}
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		b = append(b, c)
		c, err = rd.ReadByte()
	}
	return string(b)
}

func main() {
	a, b := readInt(), readInt()
	best := math.MaxInt64
	// For a fixed k, the smallest x makes k(A+x) >= B; y is then forced.
	test := func(k int) {
		x := max(0, (b+k-1)/k-a)
		best = min(best, x+k*(a+x)-b)
	}
	r := int(math.Sqrt(float64(b)))
	for r*r > b {
		r--
	}
	for (r+1)*(r+1) <= b {
		r++
	}
	r += 2
	for k := 1; k <= min(b, r); k++ { // small k directly
		test(k)
	}
	for q := 1; q <= r; q++ { // large k grouped by ceil(B/k)
		test((b + q - 1) / q)
	}
	test(max(1, (b+a-1)/a)) // boundary where x becomes 0
	fmt.Println(best)
}
